import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import extractText from 'flarum/common/utils/extractText';
/**
 * The scoreboard as a widget: whatever game is on, wherever it is placed.
 *
 * 🚨 Not the same question as the board at the head of a game thread. That one
 * is about the thread it sits on; this one is about the site — live first, then
 * the next kickoff, then the last final for a few hours so the panel is not
 * blank for six days of the week.
 *
 * 🚨 Dark in both themes, like the thread's board and for the same reason: a
 * scoreboard is a thing you look at in a stadium, and one that turns white in
 * light mode reads as a table of numbers.
 */
export default class ScoreboardWidget extends Component {
  board = null;
  loading = false;
  timer = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.board = this.attrs.board ?? null;
    if (this.attrs.board === undefined) {
      this.loading = true;
      this.refresh();
    } else {
      this.schedule();
    }
  }
  onremove() {
    if (this.timer) clearTimeout(this.timer);
  }

  /**
   * How often to ask again.
   *
   * 🚨 Every fifteen seconds while a game is being PLAYED, and almost never
   * otherwise. A widget can sit on a home page every visitor loads, so a poll
   * that ran regardless would be a request per reader per interval, all year,
   * to be told the same thing.
   *
   * 🚨 A scheduled game still needs one — otherwise the widget shows "Kickoff
   * 7:30pm" for the whole first quarter to anybody who left the tab open. Once
   * a minute, and only inside the half hour before kickoff, which is the only
   * window in which the answer can change.
   */
  schedule() {
    if (this.timer) clearTimeout(this.timer);
    if (!this.board) return;
    if (this.board.state === 'live') {
      this.timer = setTimeout(() => this.refresh(), 15000);
      return;
    }
    if (this.board.state === 'scheduled' && this.nearKickoff()) {
      this.timer = setTimeout(() => this.refresh(), 60000);
    }
  }
  nearKickoff() {
    if (!this.board?.kickoff) return false;
    const away = new Date(this.board.kickoff).getTime() - Date.now();

    // Already past kickoff counts: the feed can be a minute or two behind the
    // whistle, and that is exactly when somebody is watching this.
    return away < 1800000;
  }
  refresh() {
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/gameday/board`
    }).then(res => {
      this.board = res && res.board || null;
      this.loading = false;
      m.redraw();
    }).catch(() => {
      // A missed poll is a stale board, not a broken page. The FIRST fetch
      // failing is different — it leaves nothing to draw, and the empty state
      // below is what says so.
      this.loading = false;
      m.redraw();
    }).then(() => this.schedule());
  }
  view() {
    const s = this.attrs.settings || {};
    const b = this.board;
    const t = (k, p) => app.translator.trans(`ernestdefoe-gameday.forum.widget_${k}`, p);
    if (!b) {
      // 🚨 Nothing at all, by default. Off-season this panel would otherwise
      // say "no games" every day for months, which is a worse answer than the
      // space it takes up.
      if (this.loading || s.hideWhenEmpty !== false) return null;
      return m("div", {
        className: "GamedayWidget GamedayWidget--empty"
      }, s.title ? m("h4", {
        className: "GamedayWidget-title"
      }, s.title) : null, m("p", {
        className: "GamedayWidget-none"
      }, t('no_game')));
    }
    const link = s.showLink === false ? null : b.discussion;
    return m("div", {
      className: `GamedayWidget GamedayWidget--${b.state}${b.redZone ? ' GamedayWidget--redzone' : ''}`
    }, s.title ? m("h4", {
      className: "GamedayWidget-title"
    }, s.title) : null, m("div", {
      className: "GamedayWidget-board",
      "aria-live": "polite"
    }, m("div", {
      className: "GamedayWidget-status"
    }, b.state === 'live' ? m("span", {
      className: "GamedayWidget-live"
    }, m("span", {
      className: "GamedayWidget-pip",
      "aria-hidden": "true"
    }), t('live')) : null, m("span", {
      className: "GamedayWidget-period"
    }, this.statusLine(b, t))), b.clockStale ? m("div", {
      className: "GamedayWidget-stale"
    }, t('stale')) : null, this.side(b.away), this.side(b.home), b.down || b.redZone ? m("div", {
      className: "GamedayWidget-situation"
    }, b.down ? m("span", {
      className: "GamedayWidget-down"
    }, b.down) : null, b.redZone ? m("span", {
      className: "GamedayWidget-rz"
    }, t('red_zone')) : null) : null), link ? m("a", {
      className: "GamedayWidget-link",
      href: app.route('discussion', {
        id: `${link.id}-${link.slug}`
      })
    }, m("span", {
      className: "GamedayWidget-linkLabel"
    }, t('to_the_thread')), link.commentCount > 1 ? m("span", {
      className: "GamedayWidget-count"
    }, link.commentCount) : null) : null);
  }
  statusLine(b, t) {
    if (b.state === 'scheduled') {
      return b.kickoff ? new Date(b.kickoff).toLocaleString(undefined, {
        weekday: 'short',
        day: 'numeric',
        month: 'short',
        hour: 'numeric',
        minute: '2-digit'
      }) : t('scheduled');
    }

    // The clock beside the period where there is one worth printing — the shape
    // has already dropped it if it is stale or sitting at a period boundary.
    // The clock beside the period only where there is one worth printing —
    // shape() has already dropped it if it is stale or at a period boundary,
    // and the staleness is said on its own row below.
    if (b.state === 'live') {
      return b.clock ? `${b.periodLine} · ${b.clock}` : b.periodLine;
    }
    return b.periodLine;
  }
  side(s) {
    return m("div", {
      className: `GamedayWidget-side${s.hasBall ? ' GamedayWidget-side--ball' : ''}`
    }, m("span", {
      className: "GamedayWidget-crest"
    }, s.logo ? m("img", {
      src: s.logo,
      alt: "",
      "aria-hidden": "true",
      loading: "lazy",
      referrerpolicy: "no-referrer"
    }) : null), m("span", {
      className: "GamedayWidget-team"
    }, s.abbr || s.name), s.hasBall ? m("span", {
      className: "GamedayWidget-ball",
      title: extractText(app.translator.trans('ernestdefoe-gameday.forum.board_possession', {
        team: s.name
      }))
    }, "\u25CF") : null, m("span", {
      className: "GamedayWidget-score"
    }, s.score === null ? '–' : s.score));
  }
}
flarum.reg.add('ernestdefoe-gameday', 'forum/components/ScoreboardWidget', ScoreboardWidget);